diff_context.before:
            mcp::execute();
        }
        None => {
            error!("No command specified. Use --help for usage information.");
        }
    }
}

diff_context.after:
            scan::execute(
                token,
                *skip_crack,
                *skip_payloads,
                wordlist.clone(),
                *max_crack_attempts,
            );
        }
        Some(Commands::Version) => {
            version::execute();
        }
        Some(Commands::Mcp) => {
            mcp::execute();
        }
        Some(Commands::Server { host, port }) => {
            let runtime = tokio::runtime::Runtime::new().unwrap();
            runtime.block_on(server::execute(host, *port));
        }
        None => {
            error!("No command specified. Use --help for usage information.");
        }
    }
}
